const errorData = $input.item.json;

return {
  json: {
    sujet: `🚨 ALERTE CRITIQUE : Panne sur ${errorData.workflow.name}`,
    workflow_nom: errorData.workflow.name,
    workflow_id: errorData.workflow.id,
    execution_id: errorData.execution.id,
    message_erreur: errorData.execution.error.message || 'Erreur inconnue',
    horodatage: new Date().toLocaleString('fr-FR', { timeZone: 'Europe/Paris' })
  }
};
